import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Accept": "application/json"})

# Retrieve historical shipment data for trend analysis.
shipments_response = session.get(
    f"{BASE_URL}/shipments/history",
    params={"period": "all"},
)
shipments_response.raise_for_status()
shipment_history = shipments_response.json()

# Schedule maintenance for the specified machine.
maintenance_response = session.post(
    f"{BASE_URL}/maintenance",
    json={
        "machine_id": "MACHINE_ID",
        "activity": "Scheduled maintenance",
        "scheduled_at": "2026-11-12T09:00:00Z",
    },
)
maintenance_response.raise_for_status()
maintenance = maintenance_response.json()

# Update the ongoing industrial project's energy-efficiency metrics.
project_response = session.patch(
    f"{BASE_URL}/projects/PROJECT_ID/metrics",
    json={
        "energy_efficiency": {
            "status": "improved",
            "updated_at": "2026-11-05",
        }
    },
)
project_response.raise_for_status()
project_metrics = project_response.json()

# Generate a report covering shipment trends and the maintenance and project updates.
report_response = session.post(
    f"{BASE_URL}/reports",
    json={
        "title": "Shipment Trends and Industrial Performance Updates",
        "sections": [
            {
                "type": "shipment_analytics",
                "data": shipment_history,
            },
            {
                "type": "maintenance",
                "data": maintenance,
            },
            {
                "type": "project_metrics",
                "data": project_metrics,
            },
        ],
    },
)
report_response.raise_for_status()
report = report_response.json()

print(report)

