import requests

BASE_URL = "https://api.socbench.example"
PROPERTY_ID = "YOUR_PROPERTY_ID"
API_KEY = "YOUR_API_KEY"

headers = {
    "Authorization": f"Bearer {API_KEY}",
    "Content-Type": "application/json",
}

history_response = requests.get(
    f"{BASE_URL}/properties/{PROPERTY_ID}/ownership-history",
    headers=headers,
)
history_response.raise_for_status()
ownership_history = history_response.json()

inquiry_response = requests.post(
    f"{BASE_URL}/properties/{PROPERTY_ID}/inquiries",
    headers=headers,
    json={
        "question": "Please provide clarifications or additional information about this property's ownership history."
    },
)
inquiry_response.raise_for_status()
inquiry_response_data = inquiry_response.json()

report_response = requests.post(
    f"{BASE_URL}/reports",
    headers=headers,
    json={
        "property_id": PROPERTY_ID,
        "report_type": "custom",
        "title": "Property Ownership History Insights",
        "sections": [
            {
                "title": "Ownership History",
                "data": ownership_history,
            },
            {
                "title": "Inquiry Response",
                "data": inquiry_response_data,
            },
        ],
    },
)
report_response.raise_for_status()
custom_report = report_response.json()

print(custom_report)
